package com.guillermomolina.protos.execution;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

/**
 * I109-A / PLAT063-C source-emission structural regression guards.
 *
 * <p>These tests verify the Bytecode DSL emission source, not the
 * instructions materialized by the generated BytecodeNode.
 */
final class ProtosI109ASharedLocalEachLoweringTest {

    private static final String[] FAMILIES = {
        "Array", "Bytes", "Environment", "IdentityMap", "Map"
    };

    private static final String LOCAL_EACH_ADMISSION =
            "builder.beginIsStructuredLocalEach();";

    private static final String FOREIGN_EACH_ADMISSION =
            "builder.beginIsStructuredForeignEach();";

    private static final String IDENTITY_MAP_AT_IF_ABSENT_ADMISSION =
            "builder.beginIsStructuredIdentityMapAtIfAbsent();";

    private static final String MAP_READ_LOOKUP_ADMISSION =
            "builder.beginIsStructuredMapReadLookup();";

    private static final String LOCAL_EACH_PREPARATION =
            "builder.beginPrepareStructuredLocalEach();";

    /** I113: the shared structured phases the local each loop emits once. */
    private static final String[] OPERATIONS = {
        "StructuredHasNext",
        "StructuredPrepareChildCall",
        "StructuredAdvance",
        "StructuredFinish"
    };

    private static Path repositoryFile(String relative) {
        Path directory = Path.of("").toAbsolutePath();

        while (directory != null) {
            if (Files.isRegularFile(directory.resolve("pom.xml"))
                    && Files.isRegularFile(directory.resolve(relative))) {
                return directory.resolve(relative);
            }
            directory = directory.getParent();
        }

        throw new IllegalStateException(
                "Cannot find repository file: " + relative);
    }

    private static String read(String relative) throws IOException {
        return Files.readString(repositoryFile(relative));
    }

    private static String lowering() throws IOException {
        return read(
                "src/main/java/com/guillermomolina/protos/"
                + "execution/bytecode/lowering/"
                + "ProtosStructuredDispatchLowerer.java");
    }

    private static String activation() throws IOException {
        return read(
                "src/main/java/com/guillermomolina/protos/"
                + "execution/bytecode/activation/"
                + "ProtosBytecodeRootNode.java");
    }

    private static int occurrences(String text, String token) {
        int count = 0;
        int position = 0;

        while ((position = text.indexOf(token, position)) >= 0) {
            count++;
            position += token.length();
        }

        return count;
    }

    private static String sharedRegion(String source) {
        String first = LOCAL_EACH_ADMISSION;
        String foreign = FOREIGN_EACH_ADMISSION;

        int start = source.indexOf(first);
        int end = source.indexOf(foreign);

        assertTrue(start >= 0, "Shared local each admission missing");
        assertTrue(end > start, "Foreign each must follow local each");

        return source.substring(start, end);
    }

    private static String operationClass(String source, String name) {
        String declaration = "public static final class " + name + " {";
        int start = source.indexOf(declaration);

        assertTrue(start >= 0, "Missing operation class " + name);

        int opening = source.indexOf('{', start);
        int depth = 0;

        for (int i = opening; i < source.length(); i++) {
            char character = source.charAt(i);

            if (character == '{') {
                depth++;
            } else if (character == '}') {
                depth--;
                if (depth == 0) {
                    return source.substring(start, i + 1);
                }
            }
        }

        throw new AssertionError("Unbalanced operation class " + name);
    }

    @Test
    void fiveFamiliesShareOnePhysicalBytecodeDslLoop()
            throws IOException {
        String source = lowering();
        String region = sharedRegion(source);

        for (String operation : OPERATIONS) {
            // I113: some shared phases carry a builder-fixed constant.
            assertEquals(1, occurrences(
                    region, "builder.begin" + operation + "("),
                    operation);
            assertEquals(1, occurrences(
                    region, "builder.end" + operation + "();"),
                    operation);
        }

        assertEquals(1, occurrences(region, LOCAL_EACH_ADMISSION));
        assertEquals(1, occurrences(region, LOCAL_EACH_PREPARATION));
        assertEquals(1, occurrences(
                region, "builder.endPrepareStructuredLocalEach();"));
        assertEquals(1, occurrences(
                region, "builder.endIsStructuredLocalEach();"));

        assertEquals(1, occurrences(
                region, "builder.beginWhile();"));
        assertEquals(1, occurrences(
                region, "builder.endWhile();"));

        // I115: callbacks use the shared CallRequest dispatcher.
        assertEquals(1, occurrences(
                region, "emitCallRequest("));

        // No historical prepared-call lifecycle is recreated.
        assertEquals(0, occurrences(
                region, "emitScopedPreparedInvocation("));

        assertEquals(0, occurrences(
                region, "builder.beginCompleteClosureCall();"));

        assertEquals(0, occurrences(
                region, "builder.beginTryFinally("));

        for (String family : FAMILIES) {
            assertFalse(source.contains(
                    "builder.beginIsStructured" + family
                    + "EachCall();"),
                    "Old physical branch remains: " + family);
        }
    }

    @Test
    void preparationCallbackAdvanceAndFinishKeepTheirOrder()
            throws IOException {
        String region = sharedRegion(lowering());

        String[] sequence = {
            LOCAL_EACH_PREPARATION,
            "builder.beginWhile();",
            "builder.beginStructuredHasNext(ProtosStructuredPhase.STEP);",
            "builder.beginStructuredPrepareChildCall(ProtosStructuredPhase.CHILD);",
            "emitCallRequest(",
            "builder.beginStructuredAdvance(ProtosStructuredPhase.STEP);",
            "builder.endWhile();",
            "builder.beginStructuredFinish();"
        };

        int previous = -1;

        for (String operation : sequence) {
            int current = region.indexOf(operation);
            assertTrue(
                    current > previous,
                    "Missing or reordered operation: " + operation);
            previous = current;
        }
    }

    @Test
    void admissionUsesCapabilitiesNotSelectorText()
            throws IOException {
        String admission = operationClass(activation(), "IsStructuredLocalEach");

        for (String family : FAMILIES) {
            assertEquals(1, occurrences(admission,
                    "prepared.isStructured" + family + "Each()"),
                    "Missing capability: " + family);
        }
        assertEquals(FAMILIES.length,
                occurrences(admission, "prepared.isStructured"),
                "Admission must check exactly the five capabilities");

        assertTrue(admission.contains(
                "StructuredNativeInvocation prepared"));
        assertFalse(admission.contains("\"each\""));

        assertFalse(admission.contains(
                "OrdinarySourceCall prepared"));
        assertFalse(admission.contains(
                "NativeCall prepared"));
        assertFalse(admission.contains(
                "ImmediateResultCall prepared"));
        assertFalse(admission.contains(
                "ModuleInitializationCall prepared"));
    }

    @Test
    void preparationDelegatesToTheFiveExistingAuthorities()
            throws IOException {
        String preparation =
                operationClass(activation(), "PrepareStructuredLocalEach");

        int previous = -1;
        for (String family : FAMILIES) {
            String delegate = "return prepared.prepareStructured" + family
                    + "Each();";
            assertEquals(1, occurrences(preparation, delegate),
                    "Incorrect number of delegates: " + family);
            int guard = preparation.indexOf(
                    "if (prepared.isStructured" + family + "Each())");
            assertTrue(guard > previous,
                    "Missing or reordered preparation precedence: " + family);
            assertTrue(preparation.indexOf(delegate) > guard, family);
            previous = guard;
        }

        assertFalse(preparation.contains("\"each\""));
    }

    @Test
    void genericStructuredCallOperationsAreRetired()
            throws IOException {
        String activation = activation();
        String source = lowering();

        assertFalse(activation.contains(
                "public static final class IsStructuredCall {"));
        assertFalse(activation.contains(
                "public static final class PrepareStructuredCall {"));
        assertFalse(source.contains("builder.beginIsStructuredCall("));
        assertFalse(source.contains("builder.beginPrepareStructuredCall("));
        assertFalse(source.contains("ProtosStructuredCallKind"));
    }

    @Test
    void unrelatedDispatchFamiliesRemainPresent()
            throws IOException {
        String source = lowering();

        assertEquals(1, occurrences(
                source,
                FOREIGN_EACH_ADMISSION));

        assertEquals(1, occurrences(
                source,
                IDENTITY_MAP_AT_IF_ABSENT_ADMISSION));

        assertEquals(1, occurrences(
                source,
                MAP_READ_LOOKUP_ADMISSION));

        assertTrue(
                source.indexOf(LOCAL_EACH_ADMISSION)
                < source.indexOf(FOREIGN_EACH_ADMISSION));

        assertTrue(
                source.indexOf(FOREIGN_EACH_ADMISSION)
                < source.indexOf(IDENTITY_MAP_AT_IF_ABSENT_ADMISSION));

        assertTrue(operationClass(activation(), "IsStructuredForeignEach")
                .contains("prepared.isStructuredForeignEach()"));
        assertTrue(operationClass(activation(), "IsStructuredIdentityMapAtIfAbsent")
                .contains("prepared.isStructuredIdentityMapAtIfAbsent()"));
        assertTrue(operationClass(activation(), "IsStructuredMapReadLookup")
                .contains("prepared.isStructuredMapReadLookup()"));
    }
}
